package com.enterprise.licensing.client;
import static org.assertj.core.api.Assertions.assertThat;import com.enterprise.licensing.client.identity.ProductInstanceIdentityStore;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;import java.nio.file.*;import java.nio.file.attribute.PosixFilePermission;import java.util.Set;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class ProductInstanceIdentityStoreTest{@TempDir Path temp;@Test void identitySurvivesTomcatRestartAndCanBeSharedByKubernetesReplicas()throws Exception{var file=temp.resolve("installation/identity.json");var mapper=new ObjectMapper().registerModule(new JavaTimeModule());var first=new ProductInstanceIdentityStore(file,mapper).loadOrCreate();var restarted=new ProductInstanceIdentityStore(file,mapper).loadOrCreate();assertThat(restarted.identity()).isEqualTo(first.identity());assertThat(restarted.privateKey().getEncoded()).isEqualTo(first.privateKey().getEncoded());try{assertThat(Files.getPosixFilePermissions(file)).isEqualTo(Set.of(PosixFilePermission.OWNER_READ,PosixFilePermission.OWNER_WRITE));}catch(UnsupportedOperationException ignored){}}}
